import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Actions Menu & Preview","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/actions-and-preview.md","filePath":"user-guide/actions-and-preview.md","lastUpdated":1785124727000}'),n={name:"user-guide/actions-and-preview.md"};function s(r,e,l,d,c,h){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="actions-menu-preview" tabindex="-1">Actions Menu &amp; Preview <a class="header-anchor" href="#actions-menu-preview" aria-label="Permalink to &quot;Actions Menu &amp; Preview&quot;">​</a></h1><h2 id="actions-menu" tabindex="-1">Actions menu <a class="header-anchor" href="#actions-menu" aria-label="Permalink to &quot;Actions menu&quot;">​</a></h2><p>Every result — file, folder, or app — has a set of actions beyond &quot;just open it&quot;: locate in Explorer, copy path, run as administrator, cut/copy/paste the file itself, delete it (to the Recycle Bin) or permanently delete it, and anything a plugin adds (for example, the full Windows shell right-click menu, cascading submenus included).</p><p>Open it with the <strong>Open actions menu</strong> hotkey (<code>Ctrl+O</code> by default) or the literal Right arrow on a selected result. Inside the menu:</p><ul><li><strong>Next/Previous item</strong> — the arrow keys, or your own configured <a href="./hotkeys.html">next/previous-item hotkey</a>, move the highlight up and down the actions list. A custom binding (even something like a bare <code>Tab</code> key) is honored here exactly the same way it is in the main result list.</li><li><strong>Right arrow / Enter</strong> on an item with a submenu (e.g. a shell cascade menu like &quot;Send to&quot;) drills into it; <strong>Left arrow</strong> or <strong>Backspace</strong> (with an empty search box) backs out one level.</li><li><strong>Escape</strong> exits the actions menu, or clears the search box first if you&#39;d typed something to filter the action list.</li><li>Type to filter the visible actions by name, the same way you&#39;d filter search results.</li></ul><h2 id="full-window-results-grid" tabindex="-1">Full window results grid <a class="header-anchor" href="#full-window-results-grid" aria-label="Permalink to &quot;Full window results grid&quot;">​</a></h2><p>Double-clicking a result normally opens it, same as pressing Enter — with one exception: double- clicking the <strong>Path</strong> column instead opens the result&#39;s containing folder in Explorer, the same thing <code>Ctrl</code>+Enter does anywhere else on the row. A plugin&#39;s own custom column can define this same kind of double-click override for itself.</p><h2 id="quicklook-preview" tabindex="-1">QuickLook preview <a class="header-anchor" href="#quicklook-preview" aria-label="Permalink to &quot;QuickLook preview&quot;">​</a></h2><p>Press the <strong>QuickLook</strong> hotkey (<code>Alt+P</code> by default) on a selected result to open a preview pane docked next to the search window — images, documents, and other previewable file types render without leaving SwiftList. Press it again (or move to a result QuickLook can&#39;t preview) to close it.</p><p>Audio and video files — whatever formats WPF&#39;s built-in media playback supports without extra codecs (MP4, WMV, AVI, MOV, MP3, WAV, WMA, and a few others) — play automatically as soon as the preview opens, with a small themed transport bar (play/pause, seek, current/total time, mute) instead of a static thumbnail. Moving to a different result or closing the preview stops playback immediately. A file whose specific codec can&#39;t be decoded falls back to a static thumbnail instead.</p><p>The preview window&#39;s size is fixed and user-configurable — see <a href="./settings/general.html#preview">Settings → General → Preview</a> — and independent of how many results are currently showing. Whatever size you set, SwiftList automatically keeps the preview window fully on-screen: if it doesn&#39;t fit beside the search window on your monitor, it docks to whichever side has room, and if the configured size is larger than your monitor&#39;s usable area, the window is scaled down to fit rather than running off the edge.</p><p>If the file being previewed needs its own native handler to show a popup of its own — most commonly Word or Excel asking for a password on an encrypted document — both the quick window and the preview pane hide themselves for as long as that popup is open, since it would otherwise sit unreachable behind them. This isn&#39;t SwiftList closing or crashing: resolve the popup (enter the password, dismiss it, whatever it&#39;s asking) and both windows come back exactly as you left them, search text and selection included.</p>',12)])])}const w=t(n,[["render",s]]);export{p as __pageData,w as default};
